<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\DTO\Exam\ExamEventDTO; use Inc\DTO\Exam\ExamSessionDTO; use Inc\DTO\Exam\ExamRegistrationDTO; use Inc\Repositories\WPDBRepositories\ExamEventRepository; use Inc\Repositories\WPDBRepositories\ExamSessionRepository; use Inc\Repositories\WPDBRepositories\ExamRegistrationRepository; class ExamAccessValidator { private ExamEventRepository $eventRepo; private ExamSessionRepository $sessionRepo; private ExamRegistrationRepository $regRepo; public function __construct( ?ExamEventRepository $eventRepo = null, ?ExamSessionRepository $sessionRepo = null, ?ExamRegistrationRepository $regRepo = null ) { $this->eventRepo = $eventRepo ?? new ExamEventRepository(); $this->sessionRepo = $sessionRepo ?? new ExamSessionRepository(); $this->regRepo = $regRepo ?? new ExamRegistrationRepository(); } public function canStudentViewEvent( int $eventId, ?int $personId ): bool { $event = $this->eventRepo->find( $eventId ); if ( ! $event || 'published' !== $event->status ) { return false; } if ( ! $personId ) { return false; } return true; } public function canStudentRegister( int $eventId, ?int $personId ): bool { $event = $this->eventRepo->find( $eventId ); if ( ! $event || 'published' !== $event->status ) { return false; } $now = current_time( 'mysql', true ); if ( $now < $event->registrationOpensAt || $now > $event->registrationClosesAt ) { return false; } return true; } public function canStartAttempt( int $registrationId, int $personId ): bool { $reg = $this->regRepo->find( $registrationId ); if ( ! $reg ) { return false; } if ( 'confirmed' !== $reg->status ) { return false; } $session = $this->sessionRepo->find( $reg->sessionId ); if ( ! $session ) { return false; } $now = current_time( 'mysql', true ); if ( $now < $session->scheduledAt ) { return false; } if ( $now > $session->plannedEndAt ) { return false; } return true; } public function isRegistrationActive( int $registrationId ): bool { $reg = $this->regRepo->find( $registrationId ); return $reg && 'confirmed' === $reg->status && null !== $reg->activeSlot; } }
